def graph_from(adjacency):
    # adjacency[i] lists the values of the neighbors of the node whose value is i + 1
    nodes = [Node(i + 1) for i in range(len(adjacency))]
    for node, values in zip(nodes, adjacency):
        node.neighbors = [nodes[v - 1] for v in values]
