def reachable(start):
    seen, queue = {id(start)}, [start]
    for node in queue:
        for other in node.neighbors:
            if id(other) not in seen:
                seen.add(id(other))
                queue.append(other)
    return queue
def cloned(adjacency, start=1):
    # Clones the graph from the node with value `start`, checks the copy and returns its adjacency lists (sorted, by value).
    originals = graph_from(adjacency)
    before = [list(node.neighbors) for node in originals]
    copy = clone_graph(originals[start - 1])
    if not isinstance(copy, Node):
        raise AssertionError(f"clone_graph must return the copy of the given node, not {copy!r}")
    if [node.neighbors for node in originals] != before:
        raise AssertionError("the original graph was changed; clone_graph must only read it")
    copies = reachable(copy)
    original_ids = {id(node) for node in originals}
    if any(id(node) in original_ids for node in copies):
        raise AssertionError("the copy contains a node of the original graph; every node must be a new Node")
    values = sorted(node.val for node in copies)
    expected = sorted(node.val for node in reachable(originals[start - 1]))
    if values != expected:
        raise AssertionError(f"the copy has the nodes {values[:30]} but the graph has {expected[:30]}; copy each node exactly once")
    if copy.val != start:
        raise AssertionError(f"return the copy of the node you were given (val {start}), not the one with val {copy.val}")
    by_value = {node.val: node for node in copies}
    result = []
    for value in sorted(by_value):
        for other in by_value[value].neighbors:
            if by_value[other.val] is not other:
                raise AssertionError(f"node {value} points to a second copy of the node with val {other.val}")
        result.append(sorted(other.val for other in by_value[value].neighbors))
    return result
