def expected_combinations(candidates, target):
    """The same answer worked out another way: take the candidates one at a time and extend the combinations of every smaller total."""
    ways = {total: [] for total in range(target + 1)}
    ways[0] = [[]]
    for candidate in sorted(candidates):
        for total in range(candidate, target + 1):
            ways[total] += [combination + [candidate] for combination in ways[total - candidate]]
    return sorted(sorted(combination) for combination in ways[target])

combination-sum.solution:
def combination_sum(candidates, target):
    candidates = sorted(candidates)
    result = []
    chosen = []

    def build(start, remaining):
        if remaining == 0:
            result.append(chosen[:])           # the target is reached exactly: store a copy
            return
        for i in range(start, len(candidates)):
            if candidates[i] > remaining:
                break                          # sorted: every later candidate is too big as well
            chosen.append(candidates[i])
            build(i, remaining - candidates[i])    # i, not i + 1: the same number may be used again
            chosen.pop()

    build(0, target)
    return result

