    def __init__(self):
        self._host = None
        self._port = None
        self._tls = None
        self._timeout = 30
        self._retries = 3

    def host(self, name):
        self._host = name
        return self

    def port(self, number):
        self._port = number
        return self

    def tls(self, certificate, key):
        self._tls = (certificate, key)
        return self

