observer-event-bus.solution:
from collections import defaultdict
from typing import Callable, Any, Dict, List


class EventBus:
    def __init__(self):
        self._handlers: Dict[str, List[Callable[..., Any]]] = defaultdict(list)

    def subscribe(self, event_name: str, handler: Callable[..., Any]) -> Callable[[], None]:
        self._handlers[event_name].append(handler)

        def _unsub():
            self.unsubscribe(event_name, handler)
        return _unsub

    def unsubscribe(self, event_name: str, handler: Callable[..., Any]) -> None:
        if event_name in self._handlers:
            handlers = self._handlers[event_name]
            if handler in handlers:
                handlers.remove(handler)
                if not handlers:
                    del self._handlers[event_name]

    def publish(self, event_name: str, *args, **kwargs) -> int:
        handlers = list(self._handlers.get(event_name, []))
        for handler in handlers:
            handler(*args, **kwargs)
        return len(handlers)

