parameterized-retry-decorator.solution:
import functools
from typing import Tuple, Type


def retry(
    max_retries: int = 3,
    initial_delay: float = 0.1,
    backoff: float = 2.0,
    exceptions: Tuple[Type[BaseException], ...] = (Exception,),
    sleep_fn=None
):
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            delay = initial_delay
            for attempt in range(1, max_retries + 1):
                try:
                    return fn(*args, **kwargs)
                except exceptions:
                    if attempt >= max_retries:
                        raise
                    if sleep_fn is not None:
                        sleep_fn(delay)
                    delay *= backoff
        return wrapper
    return decorator

